import type { ButtonHTMLAttributes, ReactNode } from "react";
import "./Button.css";

export type ButtonVariant = "primary" | "brand" | "ghost";
export type ButtonSize = "sm" | "toolbar" | "md" | "xs";

export interface ButtonProps extends ButtonHTMLAttributes<HTMLButtonElement> {
  variant?: ButtonVariant;
  size?: ButtonSize;
  leadingIcon?: ReactNode;
  trailingIcon?: ReactNode;
  /** Booking `.btn-icon` — square control, no label text. Pair with `aria-label`. */
  iconOnly?: boolean;
  children?: ReactNode;
}

export function Button({
  variant = "primary",
  size = "md",
  leadingIcon,
  trailingIcon,
  iconOnly = false,
  className = "",
  type = "button",
  children,
  ...rest
}: ButtonProps) {
  const iconClass = iconOnly ? "pt-btn--icon" : "";
  const { "aria-label": ariaLabelProp, ...restBtn } = rest;
  const label =
    ariaLabelProp ?? (iconOnly && typeof children === "string" ? children : undefined);

  return (
    <button
      type={type}
      className={`pt-btn pt-btn--${variant} pt-btn--${size} ${iconClass} ${className}`.trim()}
      aria-label={label}
      {...restBtn}
    >
      {leadingIcon ? <span className="pt-btn__icon">{leadingIcon}</span> : null}
      {iconOnly ? null : children}
      {trailingIcon ? <span className="pt-btn__icon">{trailingIcon}</span> : null}
    </button>
  );
}

export function RowActions({
  children,
  className = "",
}: {
  children: ReactNode;
  className?: string;
}) {
  return <div className={`pt-row-acts ${className}`.trim()}>{children}</div>;
}

export default Button;

.pt-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 7px;
  height: var(--size-control-md, 38px);
  padding: 0 14px;
  border-radius: var(--radius-md);
  font-family: var(--type-label-button-family);
  font-size: var(--type-label-button-size);
  font-weight: var(--type-label-button-weight);
  line-height: var(--type-label-button-line);
  cursor: pointer;
  border: 1px solid transparent;
  white-space: nowrap;
  transition:
    background var(--duration-fast) ease,
    border-color var(--duration-fast) ease,
    color var(--duration-fast) ease;
}

.pt-btn__icon {
  display: inline-flex;
  flex: none;
  align-items: center;
  justify-content: center;
}

.pt-btn svg {
  flex: none;
}

.pt-btn:disabled {
  opacity: 0.5;
  cursor: not-allowed;
}

.pt-btn--xs {
  height: 28px;
  padding: 0 10px;
  font-size: 12px;
  border-radius: var(--radius-sm);
  gap: 6px;
}

.pt-btn--sm {
  height: var(--size-control-sm, 32px);
  padding: 0 11px;
  font-family: var(--type-label-button-sm-family);
  font-size: var(--type-label-button-sm-size);
  font-weight: var(--type-label-button-sm-weight);
  line-height: var(--type-label-button-sm-line);
  border-radius: var(--radius-sm);
  gap: 6px;
}

.pt-btn--toolbar {
  height: var(--size-control-toolbar, 36px);
  padding: 0 14px;
  font-family: var(--type-label-button-family);
  font-size: 13.5px;
  font-weight: 600;
  border-radius: var(--radius-md);
  gap: 7px;
}

.pt-btn--md {
  height: var(--size-control-md, 38px);
}

.pt-btn--primary {
  background: var(--accent);
  color: var(--on-brand, #fff);
  border-color: var(--accent);
}

.pt-btn--primary:hover:not(:disabled) {
  background: var(--accent-ink);
  border-color: var(--accent-ink);
}

.pt-btn--primary:active:not(:disabled) {
  background: var(--accent-pressed);
  border-color: var(--accent-pressed);
}

.pt-btn--brand {
  background: var(--surface);
  color: var(--accent);
  border-color: var(--accent);
}

.pt-btn--brand:hover:not(:disabled) {
  background: var(--accent-soft);
  color: var(--accent-ink);
  border-color: var(--accent-ink);
}

.pt-btn--brand:active:not(:disabled) {
  background: var(--accent-soft-pressed);
}

.pt-btn--ghost {
  background: var(--surface);
  color: var(--ink);
  border-color: var(--line);
}

.pt-btn--ghost:hover:not(:disabled) {
  background: var(--surface-3);
  border-color: var(--line-hover);
  color: var(--ink);
}

.pt-btn--ghost:active:not(:disabled) {
  background: var(--surface-2);
}

/* Booking `.btn-icon` — table More, composer attach, etc. */
.pt-btn--icon {
  padding: 0;
  width: var(--size-control-md, 38px);
}

.pt-btn--icon.pt-btn--sm {
  width: var(--size-control-sm, 32px);
}

.pt-btn--icon.pt-btn--toolbar {
  width: var(--size-control-toolbar, 36px);
}

.pt-btn--icon.pt-btn--xs {
  width: 27px;
  height: 27px;
}

.pt-btn--ghost.pt-btn--icon {
  color: var(--ink-2);
}

.pt-btn--ghost.pt-btn--icon:hover:not(:disabled) {
  color: var(--ink);
}

.pt-row-acts {
  display: flex;
  align-items: center;
  gap: 10px;
  flex-wrap: nowrap;
  min-width: 0;
}

/* Booking sheet `.row-acts .more-btn` — 28px, not Topbar 36px and not generic btn-icon 32px. */
.pt-row-acts .pt-btn--ghost.pt-btn--icon {
  width: 28px;
  height: 28px;
  border-color: transparent;
  background: transparent;
  color: var(--ink-3);
}

.pt-row-acts .pt-btn--ghost.pt-btn--icon:hover:not(:disabled) {
  background: var(--surface-3);
  color: var(--ink);
  border-color: var(--line);
}

.pt-row-acts .pt-btn--ghost.pt-btn--icon:active:not(:disabled) {
  background: var(--surface-2);
}
